// Lấy dữ liệu từ Webhook
const textData = $input.item.json.body || $input.item.json; 
const binaryData = $input.item.binary || {};

const groupedExams = {};

// 1. Quét qua các trường text (ten_de_X, diem_X)
for (const key in textData) {
    const match = key.match(/_(\d+)$/);
    if (match) {
        const id = match[1];
        if (!groupedExams[id]) groupedExams[id] = { json: { id: id }, binary: {} };

        if (key.startsWith('ten_de_')) groupedExams[id].json.ten_de = textData[key];
        if (key.startsWith('diem_')) groupedExams[id].json.diem_toi_da = textData[key];
    }
}

// 2. Quét qua các file binary (file_de_X, file_mau_X)
for (const key in binaryData) {
    const match = key.match(/_(\d+)$/);
    if (match) {
        const id = match[1];
        if (!groupedExams[id]) groupedExams[id] = { json: { id: id }, binary: {} };

        if (key.startsWith('file_de_')) groupedExams[id].binary.file_de = binaryData[key];

        if (key.startsWith('file_mau_')) {
            groupedExams[id].binary.file_mau = binaryData[key];

            // Chỉ lấy extension gán vào json
            const ext = binaryData[key].fileExtension;
            if (ext) {
                groupedExams[id].json.extension = ext; 
            }
        }
    }
}

// 3. Chuyển Object thành Array chuẩn
const returnItems = [];
for (const id in groupedExams) {
    if (Object.keys(groupedExams[id].json).length > 1 || Object.keys(groupedExams[id].binary).length > 0) {
        returnItems.push(groupedExams[id]);
    }
}

return returnItems;

// Basic LLM Chain thường trả về kết quả trong trường 'text'
let rawText = $input.first().json.output || "{}";

// Dọn dẹp Markdown nếu có
if (typeof rawText === 'string') {
    rawText = rawText.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
} else {
    rawText = JSON.stringify(rawText, null, 2);
}


return {
    json: {
        status: "success",
    },
    binary: {
        data: {
            data: Buffer.from(rawText, 'utf-8').toString('base64'),
            mimeType: 'application/json',
            fileName: "rubric.json",
            fileExtension: 'json'
        }
    }
};

const errorContent = JSON.stringify({
    "status": "error",
    "message": "Định dạng file không được hỗ trợ để sinh Rubric",
    "extension": $input.first().json.extension_duoc_dung
}, null, 2);

return {
    json: {
        status: "error",
        error: errorContent
    }
};
